import React, { useContext } from 'react';
import { TripContext } from '../context/TripContext';

const TripSummary = () => {
  const { families, expenses } = useContext(TripContext);

  const totalPeople = families.reduce((sum, fam) => sum + fam.numMembers, 0);
  const totalExpense = expenses.reduce((sum, exp) => sum + exp.amount, 0);

  const perPersonCost = totalPeople ? totalExpense / totalPeople : 0;

  const owed = families.map(family => {
    const share = family.numMembers * perPersonCost;
    const paid = expenses
      .filter(e => e.paidBy === family.familyName)
      .reduce((sum, e) => sum + e.amount, 0);
    return {
      family: family.familyName,
      paid,
      share,
      balance: paid - share
    };
  });

  return (
    <div style={{ marginTop: '30px' }}>
      <h3>Summary</h3>
      <p>Total Expense: ₹{totalExpense}</p>
      <p>Per Person Share: ₹{perPersonCost.toFixed(2)}</p>
      <ul>
        {owed.map((o, i) => (
          <li key={i}>
            {o.family} paid ₹{o.paid}, should pay ₹{o.share.toFixed(2)} ⇒ 
            {o.balance > 0 ? ` gets ₹${o.balance.toFixed(2)}` : ` owes ₹${(-o.balance).toFixed(2)}`}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TripSummary;
